"""Text table and grid formatters for listing records."""
import datetime
import shutil
import stat


def human_size(n):
    if n < 1024:
        return f"{n}B"
    if n < 1024**2:
        return f"{n / 1024:.1f}K"
    if n < 1024**3:
        return f"{n / 1024**2:.1f}M"
    return f"{n / 1024**3:.1f}G"


def table(items):
    headers = ["Permissions", "Size", "Modified", "Name"]
    rows = []
    for item in items:
        mode = stat.filemode(int(item.get("mode_octal", "0644"), 8))
        kind = {"dir": "d", "symlink": "l", "file": "-", "other": "?"}.get(item.get("file_type"), "?")
        mode = kind + (kind + mode[1:]) * 3
        try:
            modified = datetime.datetime.strptime(item["modified"], "%Y-%m-%dT%H:%M:%SZ").strftime("%b %d %H:%M")
        except (ValueError, KeyError):
            modified = ""
        name = item.get("name", "") + ("/" if item.get("file_type") == "dir" else "")
        rows.append([mode, human_size(item.get("size_bytes", 0)), modified, name])
    widths = [max(len(headers[i]), *(len(r[i]) for r in rows)) if rows else len(headers[i]) for i in range(4)]
    def line(values):
        return "│ " + " │ ".join(str(v).ljust(widths[i]) for i, v in enumerate(values)) + " │"
    top = "┌─" + "─┬─".join("─" * w for w in widths) + "─┐"
    mid = "├─" + "─┼─".join("─" * w for w in widths) + "─┤"
    bottom = "└─" + "─┴─".join("─" * w for w in widths) + "─┘"
    return "\n".join([top, line(headers), mid] + [line(row) for row in rows] + [bottom])


def grid(items, width=None, ignore_width=False):
    if not items:
        return ""
    if ignore_width:
        width = max(1, sum(len(i.get("name", "")) + 2 for i in items))
    elif width is None:
        width = shutil.get_terminal_size((80, 24)).columns
    names = [i.get("name", "") + ("/" if i.get("file_type") == "dir" else "") for i in items]
    cell = max(map(len, names)) + 2
    cols = max(1, width // max(1, cell))
    cols = min(cols, len(names))
    rows = (len(names) + cols - 1) // cols
    gridrows = []
    for r in range(rows):
        vals = [names[c * rows + r] for c in range(cols) if c * rows + r < len(names)]
        gridrows.append("".join(v.ljust(cell) for v in vals).rstrip())
    return "\n".join(gridrows)

