    source = os.path.abspath(filename)
    records = {}

    def add(name, kind, size, timestamp, mode, explicit, target=None):
        name = name.replace("\\", "/").strip("/")
        if not name:
            return
        parts = name.split("/")
        for i in range(1, len(parts)):
            parent = "/".join(parts[:i])
            if parent not in records:
                records[parent] = ("dir", 0, 0, 0o755, False, None)
        records[name] = (kind, size, timestamp, mode, explicit, target)

    try:
        if zipfile.is_zipfile(filename):
            with zipfile.ZipFile(filename) as zf:
                for info in zf.infolist():
                    is_dir = info.is_dir()
                    try:
                        ts = datetime(*info.date_time, tzinfo=timezone.utc).timestamp()
                    except (ValueError, OverflowError):
                        ts = 0
                    mode = (info.external_attr >> 16) & 0o7777
                    is_link = stat.S_ISLNK(mode)
                    target = None
                    if is_link:
                        try:
                            target = zf.read(info).decode("utf-8", errors="replace")
                        except (OSError, zipfile.BadZipFile):
                            target = None
                    if not mode:
                        mode = 0o775 if is_dir else 0o600
                    add(info.filename, "dir" if is_dir else "symlink" if is_link else "file",
                        0 if is_dir or is_link else info.file_size, ts, mode, True, target)
        else:
